<?php $pageTitle='Review date-sheet import'; ?>
<section class="page-heading"><div><p class="eyebrow">Mapping review</p><h1>Review imported schedule</h1><p><?= e($batch['original_filename']) ?>: <?= (int)$batch['valid_rows'] ?> ready, <?= (int)$batch['invalid_rows'] ?> invalid.</p></div><a class="secondary-button" href="<?= e(url('date-sheets/'.$cycleId.'/import')) ?>">Upload another</a></section><?php if($error):?><div class="alert error"><?= e($error) ?></div><?php endif;?><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Row</th><th>Date</th><th>Shift</th><th>Course</th><th>Programme</th><th>Semester</th><th>Status</th><th>Messages</th></tr></thead><tbody><?php foreach($rows as $row):$s=json_decode($row['source_data'],true);$m=json_decode($row['validation_messages'],true)?:[];?><tr><td><?= (int)$row['row_number'] ?></td><td><?= e($s['exam_date']??'') ?></td><td><?= e($s['shift']??'') ?></td><td><strong><?= e($s['course_code']??'') ?></strong><small class="cell-note"><?= e($s['course_name']??'') ?></small></td><td><?= e($s['programme_code']??'') ?></td><td><?= e($s['semester']??'') ?></td><td><span class="status-label <?= e($row['validation_status']) ?>"><?= e(ucfirst($row['validation_status'])) ?></span></td><td><?= e(implode(' ',$m)?:'Ready') ?></td></tr><?php endforeach;?></tbody></table></div></section><?php if($batch['status']==='review'):?><form class="commit-bar" method="post" action="<?= e(url('date-sheets/'.$cycleId.'/import/'.$batch['id'].'/commit')) ?>"><?= csrf_field() ?><p><strong>Commit validated papers?</strong><span>New course codes are created automatically.</span></p><button class="primary-button" <?= (int)$batch['valid_rows']===0?'disabled':'' ?>>Import <?= (int)$batch['valid_rows'] ?> papers</button></form><?php endif;?>
